        for c in range(w):
            if grid[r][c] != 2:
                continue
            orbit = {(r, c), (r, w - 1 - c), (h - 1 - r, c), (h - 1 - r, w - 1 - c)}
            candidates = [grid[rr][cc] for rr, cc in orbit if grid[rr][cc] != 2]
            if not candidates:
                raise ValueError(f"cannot infer symmetric value at {(r, c)}")
            # The unchanged members of the symmetry orbit identify the covered value.
            counts = {v: candidates.count(v) for v in set(candidates)}
            out[r][c] = max(counts, key=lambda v: (counts[v], -candidates.index(v)))
    return out
